import heapq
from typing import Dict, List, Tuple

def shortest_path(graph: Dict[str, List[Tuple[str, int]]], start: str, end: str) -> List[str]:
    # Check if the start and end warehouses exist in the graph
    if start not in graph or end not in graph:
        raise ValueError("Invalid start or end warehouse")

    # Priority queue for Dijkstra's algorithm
    priority_queue = [(0, start, [])]  # (distance, current_node, path)
    visited = set()

    while priority_queue:
        current_distance, current_node, path = heapq.heappop(priority_queue)

        if current_node in visited:
            continue

        visited.add(current_node)
        new_path = path + [current_node]

        if current_node == end:
            return new_path

        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited:
                heapq.heappush(priority_queue, (current_distance + weight, neighbor, new_path))

    # If there's no path to the end warehouse
    return []

from functools import lru_cache

@lru_cache(None)
def fib_recursive(n: int) -> int:
    """
    Calculate the nth Fibonacci number recursively with memoization.
    The Fibonacci sequence is defined as:
      F(0) = 0, F(1) = 1
      F(n) = F(n-1) + F(n-2) for n >= 2
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib_recursive(n - 1) + fib_recursive(n - 2)

from typing import List

def find_median_sorted_arrays(nums1: List[int], nums2: List[int]) -> float:
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1
    x, y = len(nums1), len(nums2)
    low, high = 0, x

    while low <= high:
        partitionX = (low + high) // 2
        partitionY = (x + y + 1) // 2 - partitionX

        maxX = float('-inf') if partitionX == 0 else nums1[partitionX - 1]
        minX = float('inf') if partitionX == x else nums1[partitionX]

        maxY = float('-inf') if partitionY == 0 else nums2[partitionY - 1]
        minY = float('inf') if partitionY == y else nums2[partitionY]

        if maxX <= minY and maxY <= minX:
            if (x + y) % 2 == 0:
                return (max(maxX, maxY) + min(minX, minY)) / 2
            else:
                return max(maxX, maxY)
        elif maxX > minY:
            high = partitionX - 1
        else:
            low = partitionX + 1

    raise ValueError("Input arrays are not sorted")

def custom_find(string: str, substring: str) -> int:
    """
    Returns the lowest index in `string` where substring `substring` is found.
    If the substring is not found, returns -1.
    """
    len_string = len(string)
    len_substring = len(substring)

    if len_substring == 0:
        return 0  # Based on Python specification for an empty substring.

    if len_substring > len_string:
        return -1

    for i in range(len_string - len_substring + 1):
        if string[i:i+len_substring] == substring:
            return i
    return -1

def search_rotated_sorted_array(array, target):
    """
    This function returns the index of the target in the rotated sorted array if found, otherwise -1.
    """
    start, end = 0, len(array) - 1

    while start <= end:
        mid = (start + end) // 2

        if array[mid] == target:
            return mid

        if array[start] <= array[mid]:  # left half is sorted
            if array[start] <= target < array[mid]:
                end = mid - 1
            else:
                start = mid + 1
        else:  # right half is sorted
            if array[mid] < target <= array[end]:
                start = mid + 1
            else:
                end = mid - 1

    return -1

import heapq

def dijkstra_algorithm(graph, start, end):
    """
    Implements Dijkstra's algorithm to find the shortest path in a weighted graph.

    :param graph: A dictionary representing a weighted graph.
    :param start: A string representing the starting node.
    :param end: A string representing the target node.
    :return: A tuple containing a list of nodes representing the shortest path and the total travel time.
    """
    # Min-heap priority queue
    pq = [(0, start, [])]
    visited = set()
    while pq:
        (cost, node, path) = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        path = path + [node]

        if node == end:
            return (path, cost)

        for neighbor, weight in graph.get(node, {}).items():
            if neighbor not in visited:
                heapq.heappush(pq, (cost + weight, neighbor, path))

    return ([], 0)

def union_of_intervals(intervals):
    """
    Returns the total length covered by the union of the intervals.
    """
    if not intervals:
        return 0

    # Sort intervals based on the starting point
    intervals.sort(key=lambda x: x[0])

    merged_intervals = []

    for interval in intervals:
        if not merged_intervals or merged_intervals[-1][1] < interval[0]:
            merged_intervals.append(interval)
        else:
            merged_intervals[-1][1] = max(merged_intervals[-1][1], interval[1])

    total_length = sum(end - start for start, end in merged_intervals)

    return total_length

