def search_2d_matrix(matrix: List[List[int]], target: int) -> Tuple[int, int]:
    if not matrix or not matrix[0]:
        return (-1, -1)

    row = 0
    col = len(matrix[0]) - 1

    while row < len(matrix) and col >= 0:
        if matrix[row][col] == target:
            return (row, col)
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1

    return (-1, -1)

