def all_pairs_shortest_path(adjacency_matrix: List[List[float]]) -> List[List[float]]:
    """
    Uses the Floyd-Warshall algorithm to compute the shortest paths between all pairs of nodes.
    """
    n = len(adjacency_matrix)
    # Initialize distance matrix with the given adjacency matrix
    dist = [row[:] for row in adjacency_matrix]

    # Applying Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

from collections import deque

def shortest_path(graph, start, end):
    """
    Returns the shortest path from the start intersection to the end intersection
    using Breadth-First Search.
    """
    if start not in graph or end not in graph:
        return []

    queue = deque([[start]])
    visited = set([start])

    while queue:
        path = queue.popleft()
        node = path[-1]

        if node == end:
            return path

        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(path + [neighbor])

    return []

