def search_insert(array: List[int], val: int) -> int:
    """
    Finds the index at which `val` should be inserted to maintain the sorted order of the array.
    If `val` is already present in the array, returns the index of `val`.
    """
    low, high = 0, len(array) - 1
    while low <= high:
        mid = (low + high) // 2
        if array[mid] == val:
            return mid
        elif array[mid] < val:
            low = mid + 1
        else:
            high = mid - 1
    return low

