def ternary_search(arr: List[int], left: int, right: int, key: int) -> int:
    while left <= right:
        one_third = left + (right - left) // 3
        two_third = right - (right - left) // 3

        if arr[one_third] == key:
            return one_third
        if arr[two_third] == key:
            return two_third

        if key < arr[one_third]:
            right = one_third - 1
        elif key > arr[two_third]:
            left = two_third + 1
        else:
            left = one_third + 1
            right = two_third - 1

    return -1

