def is_path_exists(vertex_count: int, edges: List[Tuple[int, int]], source: int, target: int) -> bool:
    from collections import defaultdict, deque

    # Create graph as adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Perform BFS to find path from source to target
    visited = [False] * vertex_count
    queue = deque([source])
    visited[source] = True

    while queue:
        current = queue.popleft()
        if current == target:
            return True
        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    return False

