def search_rotated_array(nums: List[int], target: int) -> int:
    """
    Finds the index of a target book ID in a rotated sorted array.

    Parameters:
    nums (List[int]): A list of integers representing a rotated sorted array of unique book IDs.
    target (int): The book ID to search for.

    Returns:
    int: The index of the target book ID in the array `nums`. Returns `-1` if the target is not found.
    """
    if not nums:
        return -1

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        # Check if the left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Right half is sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

