def findLongestIncreasingSubsequence(arr):
    """
    Returns the length of the longest increasing subsequence in the array.
    """
    if not arr:
        return 0

    lis = []

    for num in arr:
        pos = bisect_left(lis, num)
        if pos == len(lis):
            lis.append(num)
        else:
            lis[pos] = num

    return len(lis)

