def recursive_binary_search(sorted_list: list, target: int, left: int = 0, right: int = None) -> int:
    if right is None:
        right = len(sorted_list) - 1

    if left > right:
        return -1

    middle = (left + right) // 2

    if sorted_list[middle] == target:
        return middle
    elif sorted_list[middle] < target:
        return recursive_binary_search(sorted_list, target, middle + 1, right)
    else:
        return recursive_binary_search(sorted_list, target, left, middle - 1)

