def len_longest_fib_subseq(nums):
    if len(nums) < 3:
        return 0

    index = {x: i for i, x in enumerate(nums)}
    longest = {}
    max_len = 0

    for k in range(len(nums)):
        for j in range(k):
            i = index.get(nums[k] - nums[j], None)
            if i is not None and i < j:
                seq_len = longest.get((i, j), 2) + 1
                longest[j, k] = seq_len
                max_len = max(max_len, seq_len)

    return max_len if max_len >= 3 else 0

