def min_intervals_to_cover_peaks(prices):
    """
    Returns the minimum number of non-overlapping intervals needed to cover all local peaks in the prices list.
    A local peak is prices[i] such that prices[i-1] < prices[i] > prices[i+1].
    """
    if not prices or len(prices) < 3:
        return 0

    peaks = []
    n = len(prices)

    # Identify all the peaks
    for i in range(1, n - 1):
        if prices[i - 1] < prices[i] > prices[i + 1]:
            peaks.append(i)

    if not peaks:
        return 0

    intervals = 1
    current_end = peaks[0] + 1

    # Traverse through the peaks to find non-overlapping intervals
    for peak in peaks[1:]:
        if peak > current_end:
            intervals += 1
            current_end = peak + 1

    return intervals

