def longest_monotonic_increasing_subsequence(prices: list[int]) -> int:
    """
    Returns the length of the longest monotonically increasing subsequence
    in the list of integers.
    """
    if not prices:
        return 0

    sub = []
    for price in prices:
        pos = bisect.bisect_left(sub, price)
        if pos == len(sub):
            sub.append(price)
        else:
            sub[pos] = price

    return len(sub)

def bellman_ford_with_path(graph, source, destination):
    """
    Computes the shortest path travel times from the source city to all cities
    using the Bellman-Ford algorithm and reconstructs the path to the given
    destination city.

    Parameters:
    graph (dict): The graph with cities as nodes and travel times as edges.
    source (str): The starting city.
    destination (str): The destination city.

    Returns:
    tuple: (bool indicating success, list of nodes in the shortest path)
    """
    # Step 1: Initialize distances and predecessors
    dist = {node: float('inf') for node in graph}
    pred = {node: None for node in graph}
    dist[source] = 0

    # Step 2: Relax edges repeatedly |V| - 1 times
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if dist[u] + graph[u][v] < dist[v]:
                    dist[v] = dist[u] + graph[u][v]
                    pred[v] = u

    # Step 3: Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if dist[u] + graph[u][v] < dist[v]:
                return (False, [])

    # Step 4: Reconstruct path from source to destination
    path = []
    current = destination
    while current is not None:
        path.insert(0, current)
        if current == source:
            break
        current = pred[current]

    if dist[destination] == float('inf'):
        return (True, [])

    return (True, path)

