from collections import deque

def shortest_path(grid: List[List[int]]) -> int:
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return -1

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set((0, 0))

    while queue:
        r, c, dist = queue.popleft()

        if r == rows - 1 and c == cols - 1:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == 0:
                queue.append((nr, nc, dist + 1))
                visited.add((nr, nc))

    return -1

def dfs_traversal(graph, start):
    stack = [start]
    visited = set()
    traversal_order = []

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            traversal_order.append(node)
            # Add adjacent nodes to stack (in reverse order to maintain correct traversal)
            for neighbor in reversed(graph[node]):
                if neighbor not in visited:
                    stack.append(neighbor)

    return traversal_order

def length_of_lis(nums):
    """
    Returns the length of the longest strictly increasing subsequence in the list of integers.
    """
    if not nums:
        return 0

    # This list will store the longest increasing subsequence length ending at each index
    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

