def walls_and_gates(grid: List[List[int]]) -> None:
    if not grid or not grid[0]:
        return

    m, n = len(grid), len(grid[0])
    INF = 2147483647
    queue = deque()

    # Initialize the queue with all gates' positions
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                queue.append((i, j))

    # Directions for moving up, down, left and right
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # Perform BFS from all gates simultaneously
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
