import heapq

def shortest_path_with_constraints(roads, source, destination, blocked):
    # Create an adjacency list for graph representation
    graph = {}
    for u, v, t in roads:
        if (u, v) in blocked or (v, u) in blocked:
            continue
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, t))
        graph[v].append((u, t))

    # Use a priority queue to implement Dijkstra's algorithm
    pq = [(0, source)]  # (distance, node)
    distances = {source: 0}

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node == destination:
            return current_distance

        if current_distance > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances.get(neighbor, float('inf')):
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1

def find_needle_in_haystack(haystack: str, needle: str) -> int:
    """
    Implements the KMP algorithm to find the first occurrence of 'needle' in 'haystack'.
    Returns the starting index of 'needle' in 'haystack' or -1 if 'needle' is not found.
    """
    if not needle:
        return 0  # If the needle is an empty string, we return 0.

    n, m = len(haystack), len(needle)

    # Preprocess the needle to create the LPS array
    lps = [0] * m
    j = 0  # length of the previous longest prefix suffix
    i = 1
    while i < m:
        if needle[i] == needle[j]:
            j += 1
            lps[i] = j
            i += 1
        else:
            if j != 0:
                j = lps[j-1]
            else:
                lps[i] = 0
                i += 1

    # Start searching using the LPS array
    i = j = 0  # index for haystack and needle respectively
    while i < n:
        if needle[j] == haystack[i]:
            i += 1
            j += 1

        if j == m:
            return i - j  # match found

        elif i < n and needle[j] != haystack[i]:
            if j != 0:
                j = lps[j-1]
            else:
                i += 1

    return -1  # no match found

