def shortest_path(graph: Dict[int, List[Tuple[int, int]]], start: int) -> Dict[int, int]:
    """
    Computes the shortest path from the start node to all other nodes using Dijkstra's algorithm.
    If a node is unreachable from the start node, its shortest distance is set to float('inf').
    """
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]  # (distance, node)

