def Union ( parent , rank , maxValue , a , b ) :
    a = Find ( parent , a )
    b = Find ( parent , b )
    if ( a == b ) :
        return
    if ( rank [ a ] == rank [ b ] ) :
        rank [ a ] += 1
    if ( rank [ a ] < rank [ b ] ) :
        temp = a
        a = b
        b = temp
    parent [ b ] = a
