def power ( x , y ) :
    if ( y == 0 ) :
        return 1 ;
    temp = power ( x , y // 2 ) ;
    if ( y % 2 == 0 ) :
        return temp * temp ;
    else :
        return x * temp * temp ;
def nthRootSearch ( low , high , N , K ) :
    if ( low <= high ) :
        mid = ( low + high ) // 2 ;
        if ( ( power ( mid , K ) <= N ) and ( power ( mid + 1 , K ) > N ) ) :
            return mid ;
        elif ( power ( mid , K ) < N ) :
            return nthRootSearch ( mid + 1 , high , N , K ) ;
        else :
            return nthRootSearch ( low , mid - 1 , N , K ) ;
    return low ;
