def isValidLen ( s , lenn , k ) :
    n = len ( s )
    mp = dict ( )
    right = 0
    while ( right < lenn ) :
        mp [ s [ right ] ] = mp . get ( s [ right ] , 0 ) + 1
        right += 1
    if ( len ( mp ) <= k ) :
        return True
    while ( right < n ) :
        mp [ s [ right ] ] = mp . get ( s [ right ] , 0 ) + 1
        mp [ s [ right - lenn ] ] -= 1
        if ( mp [ s [ right - lenn ] ] == 0 ) :
            del mp [ s [ right - lenn ] ]
        if ( len ( mp ) <= k ) :
            return True
        right += 1
    return len ( mp ) <= k
