def KthSmallest ( A , B , N , K ) :
    M = 0
    for i in range ( N ) :
        M = max ( A [ i ] , M )
    freq = [ 0 ] * ( M + 1 )
    for i in range ( N ) :
        freq [ A [ i ] ] += B [ i ]
    sum = 0
    for i in range ( M + 1 ) :
        sum += freq [ i ]
        if ( sum >= K ) :
            return i
    return - 1
